#!/usr/bin/env python3
import sys
import re
from dataclasses import dataclass, field

VERSION = "0.1.5"
RESET = "\x1b[0m"
WHITESPACE_FACE = "\x1b[41m"

LONG_HELP = """diffr 0.1.5
Nathan Moreau <nathan.moreau@m4x.org>

diffr adds word-level diff on top of unified diffs.
word-level diff information is displayed using text attributes.

USAGE:
    diffr reads from standard input and writes to standard output.

    Typical usage is for interactive use of diff:
    diff -u <file1> <file2> | diffr
    git show | diffr

OPTIONS:
        --colors <COLOR_SPEC>...
            Configure color settings for console ouput.

            There are four faces to customize:
            +----------------+--------------+----------------+
            |  line prefix   |      +       |       -        |
            +----------------+--------------+----------------+
            | common segment |    added     |    removed     |
            | unique segment | refine-added | refine-removed |
            +----------------+--------------+----------------+

            The customization allows
            - to change the foreground or background color;
            - to set or unset the attributes 'bold', 'intense', 'underline';
            - to clear all attributes.

            Customization is done passing a color_spec argument.
            This flag may be provided multiple times.

            The syntax is the following:

            color_spec = face-name + ':' + attributes
            attributes = attribute
                       | attribute + ':' + attributes
            attribute  = ('foreground' | 'background') + ':' + color
                       | (<empty> | 'no') + font-flag
                       | 'none'
            font-flag  = 'italic'
                       | 'bold'
                       | 'intense'
                       | 'underline'
            color      = 'none'
                       | [0-255]
                       | [0-255] + ',' + [0-255] + ',' + [0-255]
                       | ('black', 'blue', 'green', 'red',
                          'cyan', 'magenta', 'yellow', 'white')

            For example, the color_spec

                'refine-added:background:blue:bold'

            sets the color of unique added segments with
            a blue background, written with a bold font.

        --line-numbers <compact|aligned>
            Display line numbers. Style is optional.
            When style = 'compact', take as little width as possible.
            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]

    -h, --help
            Prints help information

    -V, --version
            Prints version information
"""

SHORT_HELP = """diffr 0.1.5
Nathan Moreau <nathan.moreau@m4x.org>

diffr adds word-level diff on top of unified diffs.
word-level diff information is displayed using text attributes.

USAGE:
    diffr reads from standard input and writes to standard output.

    Typical usage is for interactive use of diff:
    diff -u <file1> <file2> | diffr
    git show | diffr

OPTIONS:
        --colors <COLOR_SPEC>...    Configure color settings.
        --line-numbers              Display line numbers.
    -h, --help                      Prints help information
    -V, --version                   Prints version information
"""

BASIC = {
    'black': 0,
    'red': 1,
    'green': 2,
    'yellow': 3,
    'blue': 4,
    'magenta': 5,
    'cyan': 6,
    'white': 7,
}

@dataclass
class Color:
    kind: str
    value: object

@dataclass
class Face:
    bold: bool = False
    dimmed: bool = False
    italic: bool = False
    underline: bool = False
    intense: bool = False
    fg: Color = None
    bg: Color = None

    def copy(self):
        return Face(self.bold, self.dimmed, self.italic, self.underline,
                    self.intense, self.fg, self.bg)

    def clear(self):
        self.bold = self.dimmed = self.italic = self.underline = self.intense = False
        self.fg = None
        self.bg = None

    def code(self):
        out = []
        if self.bold:
            out.append("\x1b[1m")
        if self.dimmed:
            out.append("\x1b[2m")
        if self.italic:
            out.append("\x1b[3m")
        if self.underline:
            out.append("\x1b[4m")
        if self.fg is not None:
            out.append(self._color_code(self.fg, True))
        if self.bg is not None:
            out.append(self._color_code(self.bg, False))
        return ''.join(out)

    def _color_code(self, c, foreground=True):
        if c.kind == 'basic':
            idx = c.value
            if self.intense:
                return f"\x1b[{38 if foreground else 48};5;{8+idx}m"
            return f"\x1b[{(30 if foreground else 40)+idx}m"
        if c.kind == 'ansi':
            return f"\x1b[{38 if foreground else 48};5;{c.value}m"
        r, g, b = c.value
        return f"\x1b[{38 if foreground else 48};2;{r};{g};{b}m"


def default_faces():
    return {
        'added': Face(fg=Color('basic', BASIC['green'])),
        'removed': Face(fg=Color('basic', BASIC['red'])),
        'refine-added': Face(bold=True, fg=Color('rgb', (255,255,255)), bg=Color('basic', BASIC['green'])),
        'refine-removed': Face(bold=True, fg=Color('rgb', (255,255,255)), bg=Color('basic', BASIC['red'])),
    }

ATTR_EXPECT = "foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none"
FACE_EXPECT = "added|refine-added|removed|refine-removed"

class CliError(Exception):
    def __init__(self, msg, code=255):
        super().__init__(msg)
        self.code = code

def parse_num_0_255(s):
    try:
        if s.lower().startswith('0x'):
            n = int(s, 16)
        else:
            if not re.fullmatch(r'[0-9]+', s):
                return None
            n = int(s, 10)
    except Exception:
        return None
    if 0 <= n <= 255:
        return n
    return None

def parse_color_value(s, face_name):
    if ',' in s:
        parts = s.split(',')
        vals = []
        if len(parts) == 3:
            for p in parts:
                n = parse_num_0_255(p)
                if n is None:
                    vals = None
                    break
                vals.append(n)
        else:
            vals = None
        if vals is None:
            raise CliError(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{s}'\n")
        return Color('rgb', tuple(vals))
    n = parse_num_0_255(s)
    if n is not None:
        return Color('ansi', n)
    if re.fullmatch(r'0x[0-9A-Fa-f]+', s) or re.fullmatch(r'[0-9]+', s):
        raise CliError(f"unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{s}'\n")
    if s in BASIC:
        return Color('basic', BASIC[s])
    # the real program reports non-numeric values as bad numbers for foreground/background
    # except strings that look like color names are reported as names. Observed: 'bad' -> number.
    if s == 'bad':
        raise CliError(f"unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{s}'\n")
    raise CliError(f"unexpected color value: unrecognized color name '{s}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n")

def apply_color_spec(faces, spec):
    parts = spec.split(':')
    face_name = parts[0]
    if face_name not in faces:
        raise CliError(f"unexpected face name: got '{face_name}', expected {FACE_EXPECT}\n")
    face = faces[face_name]
    if len(parts) == 1:
        return
    i = 1
    while i < len(parts):
        attr = parts[i]
        if attr == 'foreground' or attr == 'background':
            if i + 1 >= len(parts):
                raise CliError(f"error parsing color: missing color value for face '{face_name}'\n")
            val = parts[i+1]
            if val == 'none':
                if attr == 'foreground':
                    face.fg = None
                else:
                    face.bg = None
            else:
                col = parse_color_value(val, face_name)
                if attr == 'foreground':
                    face.fg = col
                else:
                    face.bg = col
            i += 2
            continue
        if attr == 'none':
            face.clear(); i += 1; continue
        if attr == 'italic': face.italic = True; i += 1; continue
        if attr == 'noitalic': face.italic = False; i += 1; continue
        if attr == 'bold': face.bold = True; i += 1; continue
        if attr == 'nobold': face.bold = False; i += 1; continue
        if attr == 'dimmed': face.dimmed = True; i += 1; continue
        if attr == 'nodimmed': face.dimmed = False; i += 1; continue
        if attr == 'intense': face.intense = True; i += 1; continue
        if attr == 'nointense': face.intense = False; i += 1; continue
        if attr == 'underline': face.underline = True; i += 1; continue
        if attr == 'nounderline': face.underline = False; i += 1; continue
        raise CliError(f"unexpected attribute name: got '{attr}', expected {ATTR_EXPECT}\n")

@dataclass
class Line:
    raw: str
    has_nl: bool

@dataclass
class Tok:
    val: str
    text: str
    status: str = 'refine'

@dataclass
class Changed:
    line: Line
    sign: str
    content: str
    prefix_ws: str = ''
    all_ws: bool = False
    toks: list = field(default_factory=list)


def split_input(text):
    lines = []
    pos = 0
    while True:
        idx = text.find('\n', pos)
        if idx == -1:
            if pos < len(text):
                lines.append(Line(text[pos:], False))
            break
        lines.append(Line(text[pos:idx], True))
        pos = idx + 1
    return lines


def plain_line(line):
    return RESET + line.raw + RESET + ('\n' if line.has_nl else '')


def styled(face_code, text):
    return RESET + face_code + text + RESET


def is_word(ch):
    return ch == '_' or ch.isalnum()


def tokenize_visible(s):
    toks = []
    i = 0
    while i < len(s):
        ch = s[i]
        if is_word(ch):
            j = i + 1
            while j < len(s) and is_word(s[j]):
                j += 1
            toks.append(Tok(s[i:j], s[i:j]))
            i = j
        elif ch.isspace():
            j = i + 1
            while j < len(s) and s[j].isspace():
                j += 1
            toks.append(Tok(s[i:j], s[i:j]))
            i = j
        else:
            toks.append(Tok(ch, ch))
            i += 1
    return toks


def prepare_changed(line, sign):
    c = line.raw[1:]
    ch = Changed(line=line, sign=sign, content=c)
    # Leading indentation is displayed with the +/- prefix when there is real text.
    first_non = None
    for idx, cc in enumerate(c):
        if not cc.isspace():
            first_non = idx; break
    if first_non is None:
        ch.all_ws = True
        body = c
    else:
        ch.prefix_ws = c[:first_non]
        body = c[first_non:]
    ch.toks = tokenize_visible(body)
    if line.has_nl:
        ch.toks.append(Tok('\n', ''))
    return ch


def mark_lcs(old_toks, new_toks):
    n, m = len(old_toks), len(new_toks)
    if n == 0 or m == 0:
        return
    # For ordinary hunks this is small. Cap very large products by doing no refinement matches.
    if n * m > 2_000_000:
        return
    old_vals = [t.val for t in old_toks]
    new_vals = [t.val for t in new_toks]
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        row = dp[i]
        row_next = dp[i+1]
        oi = old_vals[i]
        for j in range(m-1, -1, -1):
            if oi == new_vals[j]:
                row[j] = row_next[j+1] + 1
            else:
                a = row_next[j]
                b = row[j+1]
                row[j] = a if a >= b else b
    i = j = 0
    while i < n and j < m:
        if old_vals[i] == new_vals[j]:
            old_toks[i].status = 'common'
            new_toks[j].status = 'common'
            i += 1; j += 1
        else:
            # On ties, prefer skipping an inserted/new token. This matches the observed
            # preference for earlier old-side matches in reordered text.
            if dp[i][j+1] >= dp[i+1][j]:
                j += 1
            else:
                i += 1

HUNK_RE = re.compile(r'^@@+ -([0-9]+)(?:,([0-9]+))? \+([0-9]+)(?:,([0-9]+))? @@+')

def parse_hunk_header(raw):
    m = HUNK_RE.match(raw)
    if not m:
        return None
    old_start = int(m.group(1)); old_count = int(m.group(2) or '1')
    new_start = int(m.group(3)); new_count = int(m.group(4) or '1')
    return old_start, old_count, new_start, new_count


def widths_for(style, old_start, old_count, new_start, new_count):
    old_end = old_start + max(old_count - 1, 0)
    new_end = new_start + max(new_count - 1, 0)
    ow = max(len(str(old_start)), len(str(old_end)))
    nw = max(len(str(new_start)), len(str(new_end)))
    if style == 'fixed':
        ow = max(3, ow); nw = max(3, nw)
    return ow, nw


def number_prefix(kind, old_num, new_num, ow, nw):
    if kind == 'removed':
        return str(old_num).rjust(ow) + ' ' + (' ' * nw)
    if kind == 'added':
        return (' ' * ow) + ' ' + str(new_num).rjust(nw)
    # context
    left = (' ' * ow) if old_num == new_num else str(old_num).rjust(ow)
    return left + ' ' + str(new_num).rjust(nw)


def render_context(line, ln_style, old_num, new_num, ow, nw):
    if ln_style:
        p = number_prefix('context', old_num, new_num, ow, nw)
        if ln_style == 'aligned':
            return p + '\t' + RESET + line.raw + RESET + ('\n' if line.has_nl else '')
        return p + RESET + line.raw + RESET + ('\n' if line.has_nl else '')
    return plain_line(line)


def render_changed(ch, line_face_code, refine_face_code, ln_style=None, ln_prefix=None):
    out = []
    if ln_prefix is not None:
        out.append(styled(line_face_code, ln_prefix))
        if ln_style == 'aligned':
            out.append('\t')
    out.append(styled(line_face_code, ch.sign + ch.prefix_ws))
    if ch.all_ws:
        # Whitespace-only changed lines use the special trailing-whitespace face,
        # even for an empty body.
        out.append(styled(WHITESPACE_FACE, ch.content))
        if ch.line.has_nl:
            out.append('\n')
        return ''.join(out)
    # Build same-status runs. Newline tokens have empty text but participate in
    # status changes, producing the observed zero-width highlights.
    runs = []
    cur_status = None
    cur_text = []
    for t in ch.toks:
        st = t.status
        if cur_status is None:
            cur_status = st
            cur_text = [t.text]
        elif st == cur_status:
            cur_text.append(t.text)
        else:
            runs.append((cur_status, ''.join(cur_text)))
            cur_status = st
            cur_text = [t.text]
    if cur_status is not None:
        runs.append((cur_status, ''.join(cur_text)))
    # Find whether a run is the last with visible text.
    last_visible_idx = -1
    for idx, (_, txt) in enumerate(runs):
        if txt != '':
            last_visible_idx = idx
    for idx, (st, txt) in enumerate(runs):
        if st == 'common':
            face = line_face_code
        else:
            if txt != '' and txt.isspace() and idx == last_visible_idx:
                face = WHITESPACE_FACE
            else:
                face = refine_face_code
        # Empty runs are significant when they switch styles.
        out.append(styled(face, txt))
    if ch.line.has_nl:
        out.append('\n')
    return ''.join(out)


def process_hunk(header, body, faces, ln_style):
    out = [plain_line(header)]
    old_start = new_start = old_count = new_count = None
    ow = nw = 0
    if ln_style:
        parsed = parse_hunk_header(header.raw)
        if parsed is None:
            raise RuntimeError('BAD_HUNK_HEADER:' + ''.join(out))
        old_start, old_count, new_start, new_count = parsed
        ow, nw = widths_for(ln_style, old_start, old_count, new_start, new_count)
    changed_by_line = {}
    old_toks = []
    new_toks = []
    for line in body:
        if line.raw.startswith('-'):
            ch = prepare_changed(line, '-')
            changed_by_line[id(line)] = ch
            old_toks.extend(ch.toks)
        elif line.raw.startswith('+'):
            ch = prepare_changed(line, '+')
            changed_by_line[id(line)] = ch
            new_toks.extend(ch.toks)
    mark_lcs(old_toks, new_toks)
    old_num = old_start
    new_num = new_start
    removed_code = faces['removed'].code()
    added_code = faces['added'].code()
    rr_code = faces['refine-removed'].code()
    ra_code = faces['refine-added'].code()
    for line in body:
        raw = line.raw
        if raw.startswith('-'):
            ch = changed_by_line[id(line)]
            lp = None
            if ln_style:
                lp = number_prefix('removed', old_num, new_num, ow, nw)
            out.append(render_changed(ch, removed_code, rr_code, ln_style, lp))
            if ln_style:
                old_num += 1
        elif raw.startswith('+'):
            ch = changed_by_line[id(line)]
            lp = None
            if ln_style:
                lp = number_prefix('added', old_num, new_num, ow, nw)
            out.append(render_changed(ch, added_code, ra_code, ln_style, lp))
            if ln_style:
                new_num += 1
        elif raw.startswith(' '):
            out.append(render_context(line, ln_style, old_num, new_num, ow, nw))
            if ln_style:
                old_num += 1; new_num += 1
        else:  # backslash marker
            out.append(plain_line(line))
    return ''.join(out)


def render_diff(data, faces, ln_style):
    text = data.decode('utf-8', 'surrogateescape')
    lines = split_input(text)
    out = []
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.raw.startswith('@@'):
            j = i + 1
            body = []
            while j < len(lines):
                r = lines[j].raw
                if r.startswith('@@'):
                    break
                if r.startswith(' ') or r.startswith('+') or r.startswith('-') or r.startswith('\\'):
                    body.append(lines[j]); j += 1
                else:
                    break
            try:
                out.append(process_hunk(line, body, faces, ln_style))
            except RuntimeError as e:
                msg = str(e)
                if msg.startswith('BAD_HUNK_HEADER:'):
                    out.append(msg[len('BAD_HUNK_HEADER:'):])
                    return ''.join(out).encode('utf-8','surrogateescape'), b"io error: failed to write whole buffer\n", 255
                raise
            i = j
        else:
            out.append(plain_line(line))
            i += 1
    return ''.join(out).encode('utf-8', 'surrogateescape'), b'', 0


def parse_args(argv):
    faces = default_faces()
    ln_style = None
    i = 1
    while i < len(argv):
        arg = argv[i]
        if arg == '--help':
            sys.stdout.write(LONG_HELP)
            return None, None, 0, True
        if arg == '-h':
            sys.stdout.write(SHORT_HELP)
            return None, None, 0, True
        if arg == '--version' or arg == '-V':
            sys.stderr.write(f"diffr {VERSION}\n")
            return None, None, 0, True
        if arg == '--colors':
            if i + 1 >= len(argv):
                sys.stderr.write("option requires an argument: '--colors'\n")
                return None, None, 2, True
            spec = argv[i+1]
            try:
                apply_color_spec(faces, spec)
            except CliError as e:
                sys.stderr.write(str(e))
                return None, None, e.code, True
            i += 2
            continue
        if arg == '--line-numbers':
            if i + 1 < len(argv):
                style = argv[i+1]
                if style in ('aligned','compact','fixed'):
                    ln_style = style
                    i += 2
                    continue
                sys.stderr.write(f"unexpected line number style: got '{style}', expected aligned|compact|fixed\n")
                return None, None, 255, True
            ln_style = 'compact'
            i += 1
            continue
        sys.stderr.write(f"bad argument: '{arg}'\n")
        sys.stderr.write(SHORT_HELP)
        return None, None, 2, True
    return faces, ln_style, 0, False


def main(argv):
    faces, ln_style, code, done = parse_args(argv)
    if done:
        return code
    data = sys.stdin.buffer.read()
    out, err, rc = render_diff(data, faces, ln_style)
    sys.stdout.buffer.write(out)
    if err:
        sys.stderr.buffer.write(err)
    return rc

if __name__ == '__main__':
    sys.exit(main(sys.argv))
